mapper.select:
select id, order_no, return_user_name, return_user_employee_no, return_user_department_name, receiver_name, reason, approval_status, created_at from return_order
and approval_status = #{approvalStatus}
and order_no like concat('%',#{orderNo},'%')
and return_user_name like concat('%',#{returnUserName},'%')
and return_user_employee_no like concat('%',#{returnUserEmployeeNo},'%')
and return_user_department_name like concat('%',#{returnUserDepartmentName},'%')
and created_at >= #{startDate}
and created_at <= #{endDate}
